const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const africaGeom = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
    .filter(ee.Filter.eq('continent', 'Africa'))
    .union();

  const startYear = 2003;
  const endYear = 2019;

  // 2. Data Acquisition
  const landCover = ee.ImageCollection('MODIS/006/MCD12Q1');

  const image2003 = landCover.filterDate(`${startYear}-01-01`, `${startYear}-12-31`).first();
  const image2019 = landCover.filterDate(`${endYear}-01-01`, `${endYear}-12-31`).first();

  // Data Availability Check (C1)
  if (!image2003.getInfo() || !image2019.getInfo()) {
    console.log(`Image not found for 2003: ${!image2003.getInfo()}`);
    console.log(`Image not found for 2019: ${!image2019.getInfo()}`);
    console.log("C1: Empty Collection (No images found for one or both years).");
    return;
  }

  // 3. Processing: Create a binary mask for cropland classes (12 and 14)
  // LC_Type1: IGBP classification
  // 12: Croplands
  // 14: Cropland/Natural Vegetation Mosaics
  const getCropMask = function(image) {
    const igbp = image.select('LC_Type1');
    return igbp.eq(12).or(igbp.eq(14));
  };

  const cropMask2003 = getCropMask(image2003);
  const cropMask2019 = getCropMask(image2019);

  // 4. Calculation: Calculate the area of cropland for each year
  const areaImage = ee.Image.pixelArea(); // Area in sq meters

  const calculateCropArea = function(mask, geometry) {
    const area = mask.multiply(areaImage).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 3000, // Use a larger scale for continental analysis to avoid timeout
      maxPixels: 1e12
    });
    return ee.Number(area.values().get(0));
  };

  const cropArea2003_m2 = calculateCropArea(cropMask2003, africaGeom);
  const cropArea2019_m2 = calculateCropArea(cropMask2019, africaGeom);

  // Get Info
  const cropArea2003_km2 = ee.Number(cropArea2003_m2).divide(1e6).getInfo();
  const cropArea2019_km2 = ee.Number(cropArea2019_m2).divide(1e6).getInfo();

  // 5. Validation & Final Answer
  if (cropArea2003_km2 === null || cropArea2019_km2 === null) {
      console.log("C3: Calculation Failure (Result is None/NaN).");
      return;
  }

  if (cropArea2003_km2 === 0 || cropArea2019_km2 === 0) {
      console.log(`2003 Crop Area (km2): ${cropArea2003_km2.toFixed(0)}`);
      console.log(`2019 Crop Area (km2): ${cropArea2019_km2.toFixed(0)}`);
      console.log("C2: No Valid Pixels (Area calculation resulted in zero).");
      return;
  }

  const areaIncrease_km2 = cropArea2019_km2 - cropArea2003_km2;
  const threshold_km2 = 400000;

  console.log(`2003 Total Crop Area (km2): ${Math.round(cropArea2003_km2).toLocaleString()}`);
  console.log(`2019 Total Crop Area (km2): ${Math.round(cropArea2019_km2).toLocaleString()}`);
  console.log(`Increase in Crop Area (km2): ${Math.round(areaIncrease_km2).toLocaleString()}`);
  console.log(`Threshold (km2): ${threshold_km2.toLocaleString()}`);

  if (areaIncrease_km2 > threshold_km2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error: ${e.toString()}`);
    console.log("D");
  }
}

initEE();
